<!-- @FIGURE_UI_BEGIN -->
<strong style="font-size:12px">Guided demo</strong>
<p id="demoNarration" style="margin:0;font-size:11px;line-height:1.45;color:#222"></p>
<span style="display:flex;gap:6px;align-items:center">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel" style="font-size:11px"></span>
  <button onclick="nextStep()">▶</button>
</span>
<hr style="width:100%;border:0;border-top:1px solid #dcdfe3;margin:4px 0">
<label>Focus vertex
  <select id="vertexFocusInput" onchange="toggle_vertexFocus(this.value)">
    <option value="none">none</option>
    <option value="1">1</option>
    <option value="2">2</option>
    <option value="3">3</option>
    <option value="4">4</option>
    <option value="5">5</option>
  </select>
</label>
<label>Endpoint u: <output id="endpointUVal">1</output>
  <input id="endpointUInput" type="range" min="1" max="5" step="1" value="1"
    oninput="document.getElementById('endpointUVal').value=this.value;update_endpointU(+this.value)">
</label>
<label>Endpoint v: <output id="endpointVVal">3</output>
  <input id="endpointVInput" type="range" min="1" max="5" step="1" value="3"
    oninput="document.getElementById('endpointVVal').value=this.value;update_endpointV(+this.value)">
</label>
<button id="edgeEditInput" onclick="trigger_edgeEdit()">Add / remove edge {u,v}</button>
<button onclick="resetGraphBtn()">↺ Reset graph</button>
<span style="font-size:10.5px;color:#555;line-height:1.4">Click an edge, a list record, or a matrix <b>1</b> to light up all copies of that edge. Click a circle to focus a vertex.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  var W = 920, H = 330;
  draw.viewbox(0, 0, W, H);

  /* ── palette ─────────────────────────────────────────── */
  var GRAY = '#d4d4d4', BLACK = '#000';
  var ACC = '#e8480c', ACC_BG = '#fbd9cb';
  var FOC = '#2f7fd0', FOC_BG = '#d5e7f8';
  var ADD = '#1a9850', ADD_BG = '#c9edd8';
  var GHO = '#9a9a9a', GHO_BG = '#ededed';

  /* ── model ───────────────────────────────────────────── */
  var ORIG = { 1: [2, 5], 2: [1, 5, 3, 4], 3: [2, 4], 4: [2, 5, 3], 5: [4, 1, 2] };
  function copyAdj() { var o = {}; for (var i = 1; i <= 5; i++) o[i] = ORIG[i].slice(); return o; }
  var adj = copyAdj();
  var ghosts = [];          // removed records kept as gray strike-through
  var op = null;            // {type:'added'|'removed', u, v}
  var sel = null;           // [u,v] selected edge
  var focus = 'none';
  var eu = 1, ev = 3;
  var pendingActive = false; // only true once the user actually moves an endpoint slider

  function has(u, v) { return adj[u] && adj[u].indexOf(v) >= 0; }
  function deg(u) { return adj[u].length; }

  function doAdd(u, v) {
    if (u === v || has(u, v)) { op = null; return; }
    adj[u].push(v); adj[v].push(u); ghosts = []; op = { type: 'added', u: u, v: v };
  }
  function doRemove(u, v) {
    if (u === v || !has(u, v)) { op = null; return; }
    var iu = adj[u].indexOf(v), iv = adj[v].indexOf(u);
    adj[u].splice(iu, 1); adj[v].splice(iv, 1);
    ghosts = [{ row: u, index: iu, val: v }, { row: v, index: iv, val: u }];
    op = { type: 'removed', u: u, v: v };
  }

  /* ── geometry (compact: large effective type) ────────── */
  var P = { 1: [50, 78], 2: [172, 78], 3: [238, 142], 4: [176, 212], 5: [50, 212] };
  var R = 19;

  var HEADX = 290, HEADW = 30, TOPY = 36, ROWH = 36;
  var RECW = 50, FLDW = 25, RECH = 27;
  function recX(k) { return 348 + 66 * k; }

  var MX = 710, MY = 40, CS = 36;

  var LABY = 288;

  /* ── small helpers ───────────────────────────────────── */
  function txt(s, x, y, size, color, anchor) {
    return draw.plain(String(s))
      .font({ family: 'Georgia, Times New Roman, serif', size: size, anchor: anchor || 'middle' })
      .fill(color || BLACK)
      .attr({ x: x, y: y, 'dominant-baseline': 'central' });
  }
  function arrow(x1, y1, x2, y2, color, w) {
    var g = draw.group(), ah = 6.5;
    g.line(x1, y1, x2 - ah + 1, y2).stroke({ color: color, width: w || 1.5, linecap: 'round' });
    g.polygon([[x2, y2], [x2 - ah, y2 - 4], [x2 - ah, y2 + 4]]).fill(color);
    return g;
  }
  function inter(el, tip, title, body) {
    el.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(tip, e); })
      .on('mouseleave', function () { hideTooltip(); });
    if (title) el.on('click', function () { showPopup(title, body); });
    return el;
  }
  function edgeList() {
    var out = [], seen = {};
    for (var u = 1; u <= 5; u++) for (var i = 0; i < adj[u].length; i++) {
      var v = adj[u][i], a = Math.min(u, v), b = Math.max(u, v), k = a + '-' + b;
      if (!seen[k]) { seen[k] = 1; out.push([a, b]); }
    }
    return out;
  }
  function isSel(u, v) { return sel && ((sel[0] === u && sel[1] === v) || (sel[0] === v && sel[1] === u)); }
  function isOp(u, v) { return op && ((op.u === u && op.v === v) || (op.u === v && op.v === u)); }

  function rowItems(r) {
    var items = adj[r].map(function (v) { return { val: v, st: 'normal' }; });
    for (var i = 0; i < ghosts.length; i++) {
      var g = ghosts[i];
      if (g.row === r) items.splice(Math.min(g.index, items.length), 0, { val: g.val, st: 'ghost' });
    }
    if (op && op.type === 'added' && (r === op.u || r === op.v)) {
      var t = (r === op.u) ? op.v : op.u;
      for (var j = 0; j < items.length; j++) if (items[j].val === t && items[j].st === 'normal') items[j].st = 'added';
    }
    return items;
  }

  /* ── selection / focus actions ───────────────────────── */
  function selectEdge(u, v, popup) {
    sel = [u, v]; focus = 'none';
    document.getElementById('vertexFocusInput').value = 'none';
    render();
    if (popup) showPopup('Edge {' + u + ',' + v + '}',
      'This single undirected edge is stored FOUR times: as record ' + v + ' in list[' + u + '], as record ' + u +
      ' in list[' + v + '], and as matrix cells (' + u + ',' + v + ') and (' + v + ',' + u + '). That duplication is why the list form holds 2|E| records and why the matrix is symmetric.');
  }
  function selectVertex(i) {
    focus = String(i); sel = null;
    document.getElementById('vertexFocusInput').value = String(i);
    render();
    showPopup('Vertex ' + i,
      'Vertex ' + i + ' has degree ' + deg(i) + '. The same number appears three ways: ' + deg(i) +
      ' incident edges in the drawing, ' + deg(i) + ' records in its chain, and a row sum of ' + deg(i) +
      ' in the matrix. The matrix still spends 5 cells on this row even where there is no edge.');
  }

  /* ── caption (hidden in the default state) ───────────── */
  function caption() {
    if (sel) {
      var u = sel[0], v = sel[1];
      return 'edge {' + u + ',' + v + '}  →  list[' + u + '] and list[' + v + ']; cells (' + u + ',' + v + ') and (' + v + ',' + u + ')  —  1 edge, 4 stored copies';
    }
    if (focus !== 'none') {
      var f = +focus;
      return 'vertex ' + f + '  →  neighbours {' + adj[f].join(', ') + '}:  degree ' + deg(f) + ' = chain length ' + deg(f) + ' = row sum ' + deg(f);
    }
    if (op) {
      if (op.type === 'added') return 'added {' + op.u + ',' + op.v + '}  →  one record into list[' + op.u + '] AND list[' + op.v + '];  cells (' + op.u + ',' + op.v + ') and (' + op.v + ',' + op.u + ') flipped 0→1';
      return 'removed {' + op.u + ',' + op.v + '}  →  two chains walked to unlink two records (gray);  in the matrix just two writes 1→0';
    }
    return null;
  }

  /* ── render ──────────────────────────────────────────── */
  function render() {
    draw.clear();
    draw.rect(W, H).fill('#fff');

    var pend = pendingActive && (eu !== ev);

    /* ---------- panel (a) : graph ---------- */
    if (op && op.type === 'removed') {
      draw.line(P[op.u][0], P[op.u][1], P[op.v][0], P[op.v][1])
        .stroke({ color: GHO, width: 2.4, dasharray: '6,5' });
    }
    var edges = edgeList();
    edges.forEach(function (e) {
      var a = P[e[0]], b = P[e[1]], col = BLACK, w = 1.5;
      if (isSel(e[0], e[1])) { col = ACC; w = 4.2; }
      else if (focus !== 'none' && (e[0] === +focus || e[1] === +focus)) { col = FOC; w = 3.8; }
      else if (op && op.type === 'added' && isOp(e[0], e[1])) { col = ADD; w = 3.8; }
      draw.line(a[0], a[1], b[0], b[1]).stroke({ color: col, width: w, linecap: 'round' });
    });
    if (pend && !has(eu, ev)) {
      draw.line(P[eu][0], P[eu][1], P[ev][0], P[ev][1])
        .stroke({ color: '#8a8a8a', width: 1.5, dasharray: '4,5' });
    }
    edges.forEach(function (e) {
      var a = P[e[0]], b = P[e[1]];
      var hit = draw.line(a[0], a[1], b[0], b[1])
        .stroke({ color: '#000', width: 13, opacity: 0 })
        .attr({ 'pointer-events': 'stroke' });
      inter(hit, 'edge {' + e[0] + ',' + e[1] + '} — click to see its 2 list records and 2 matrix cells');
      hit.on('click', function () { selectEdge(e[0], e[1], true); });
