    oninput="document.getElementById('endpointVVal').value=this.value;update_endpointV(+this.value)">
</label>
<button id="edgeEditInput" onclick="trigger_edgeEdit()">Add / remove edge {u,v}</button>
<button onclick="resetGraphBtn()">↺ Reset graph</button>
<span style="font-size:10.5px;color:#555;line-height:1.4">Click an edge, a list record, or a matrix <b>1</b> to light up all copies of that edge. Click a circle to focus a vertex.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  var W = 920, H = 330;
  draw.viewbox(0, 0, W, H);

  /* ── palette ─────────────────────────────────────────── */
  var GRAY = '#d4d4d4', BLACK = '#000';
  var ACC = '#e8480c', ACC_BG = '#fbd9cb';
  var FOC = '#2f7fd0', FOC_BG = '#d5e7f8';
  var ADD = '#1a9850', ADD_BG = '#c9edd8';
  var GHO = '#9a9a9a', GHO_BG = '#ededed';

  /* ── model ───────────────────────────────────────────── */
  var ORIG = { 1: [2, 5], 2: [1, 5, 3, 4], 3: [2, 4], 4: [2, 5, 3], 5: [4, 1, 2] };
  function copyAdj() { var o = {}; for (var i = 1; i <= 5; i++) o[i] = ORIG[i].slice(); return o; }
  var adj = copyAdj();
  var ghosts = [];          // removed records kept as gray strike-through
  var op = null;            // {type:'added'|'removed', u, v}
  var sel = null;           // [u,v] selected edge
  var focus = 'none';
  var eu = 1, ev = 3;
  var pendingActive = false; // only true once the user actually moves an endpoint slider

  function has(u, v) { return adj[u] && adj[u].indexOf(v) >= 0; }
  function deg(u) { return adj[u].length; }

  function doAdd(u, v) {
    if (u === v || has(u, v)) { op = null; return; }
    adj[u].push(v); adj[v].push(u); ghosts = []; op = { type: 'added', u: u, v: v };
  }
  function doRemove(u, v) {
    if (u === v || !has(u, v)) { op = null; return; }
    var iu = adj[u].indexOf(v), iv = adj[v].indexOf(u);
    adj[u].splice(iu, 1); adj[v].splice(iv, 1);
    ghosts = [{ row: u, index: iu, val: v }, { row: v, index: iv, val: u }];
    op = { type: 'removed', u: u, v: v };
  }

  /* ── geometry (compact: large effective type) ────────── */
  var P = { 1: [50, 78], 2: [172, 78], 3: [238, 142], 4: [176, 212], 5: [50, 212] };
  var R = 19;

  var HEADX = 290, HEADW = 30, TOPY = 36, ROWH = 36;
  var RECW = 50, FLDW = 25, RECH = 27;
  function recX(k) { return 348 + 66 * k; }

  var MX = 710, MY = 40, CS = 36;

  var LABY = 288;

  /* ── small helpers ───────────────────────────────────── */
  function txt(s, x, y, size, color, anchor) {
    return draw.plain(String(s))
      .font({ family: 'Georgia, Times New Roman, serif', size: size, anchor: anchor || 'middle' })
      .fill(color || BLACK)
      .attr({ x: x, y: y, 'dominant-baseline': 'central' });
  }
  function arrow(x1, y1, x2, y2, color, w) {
    var g = draw.group(), ah = 6.5;
    g.line(x1, y1, x2 - ah + 1, y2).stroke({ color: color, width: w || 1.5, linecap: 'round' });
    g.polygon([[x2, y2], [x2 - ah, y2 - 4], [x2 - ah, y2 + 4]]).fill(color);
    return g;
  }
  function inter(el, tip, title, body) {
    el.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(tip, e); })
      .on('mouseleave', function () { hideTooltip(); });
    if (title) el.on('click', function () { showPopup(title, body); });
    return el;
  }
  function edgeList() {
    var out = [], seen = {};
    for (var u = 1; u <= 5; u++) for (var i = 0; i < adj[u].length; i++) {
      var v = adj[u][i], a = Math.min(u, v), b = Math.max(u, v), k = a + '-' + b;
      if (!seen[k]) { seen[k] = 1; out.push([a, b]); }
    }
    return out;
  }
  function isSel(u, v) { return sel && ((sel[0] === u && sel[1] === v) || (sel[0] === v && sel[1] === u)); }
  function isOp(u, v) { return op && ((op.u === u && op.v === v) || (op.u === v && op.v === u)); }

  function rowItems(r) {
    var items = adj[r].map(function (v) { return { val: v, st: 'normal' }; });
    for (var i = 0; i < ghosts.length; i++) {
      var g = ghosts[i];
      if (g.row === r) items.splice(Math.min(g.index, items.length), 0, { val: g.val, st: 'ghost' });
    }
    if (op && op.type === 'added' && (r === op.u || r === op.v)) {
      var t = (r === op.u) ? op.v : op.u;
      for (var j = 0; j < items.length; j++) if (items[j].val === t && items[j].st === 'normal') items[j].st = 'added';
    }
    return items;
  }

  /* ── selection / focus actions ───────────────────────── */
  function selectEdge(u, v, popup) {
    sel = [u, v]; focus = 'none';
    document.getElementById('vertexFocusInput').value = 'none';
    render();
    if (popup) showPopup('Edge {' + u + ',' + v + '}',
      'This single undirected edge is stored FOUR times: as record ' + v + ' in list[' + u + '], as record ' + u +
      ' in list[' + v + '], and as matrix cells (' + u + ',' + v + ') and (' + v + ',' + u + '). That duplication is why the list form holds 2|E| records and why the matrix is symmetric.');
  }
  function selectVertex(i) {
    focus = String(i); sel = null;
    document.getElementById('vertexFocusInput').value = String(i);
    render();
    showPopup('Vertex ' + i,
      'Vertex ' + i + ' has degree ' + deg(i) + '. The same number appears three ways: ' + deg(i) +
      ' incident edges in the drawing, ' + deg(i) + ' records in its chain, and a row sum of ' + deg(i) +
      ' in the matrix. The matrix still spends 5 cells on this row even where there is no edge.');
  }

  /* ── caption (hidden in the default state) ───────────── */
  function caption() {
    if (sel) {
      var u = sel[0], v = sel[1];
      return 'edge {' + u + ',' + v + '}  →  list[' + u + '] and list[' + v + ']; cells (' + u + ',' + v + ') and (' + v + ',' + u + ')  —  1 edge, 4 stored copies';
    }
    if (focus !== 'none') {
      var f = +focus;
      return 'vertex ' + f + '  →  neighbours {' + adj[f].join(', ') + '}:  degree ' + deg(f) + ' = chain length ' + deg(f) + ' = row sum ' + deg(f);
    }
    if (op) {
      if (op.type === 'added') return 'added {' + op.u + ',' + op.v + '}  →  one record into list[' + op.u + '] AND list[' + op.v + '];  cells (' + op.u + ',' + op.v + ') and (' + op.v + ',' + op.u + ') flipped 0→1';
      return 'removed {' + op.u + ',' + op.v + '}  →  two chains walked to unlink two records (gray);  in the matrix just two writes 1→0';
    }
    return null;
  }

  /* ── render ──────────────────────────────────────────── */
  function render() {
    draw.clear();
    draw.rect(W, H).fill('#fff');

    var pend = pendingActive && (eu !== ev);

    /* ---------- panel (a) : graph ---------- */
    if (op && op.type === 'removed') {
      draw.line(P[op.u][0], P[op.u][1], P[op.v][0], P[op.v][1])
        .stroke({ color: GHO, width: 2.4, dasharray: '6,5' });
    }
    var edges = edgeList();
    edges.forEach(function (e) {
      var a = P[e[0]], b = P[e[1]], col = BLACK, w = 1.5;
      if (isSel(e[0], e[1])) { col = ACC; w = 4.2; }
      else if (focus !== 'none' && (e[0] === +focus || e[1] === +focus)) { col = FOC; w = 3.8; }
      else if (op && op.type === 'added' && isOp(e[0], e[1])) { col = ADD; w = 3.8; }
      draw.line(a[0], a[1], b[0], b[1]).stroke({ color: col, width: w, linecap: 'round' });
    });
    if (pend && !has(eu, ev)) {
      draw.line(P[eu][0], P[eu][1], P[ev][0], P[ev][1])
        .stroke({ color: '#8a8a8a', width: 1.5, dasharray: '4,5' });
    }
    edges.forEach(function (e) {
      var a = P[e[0]], b = P[e[1]];
      var hit = draw.line(a[0], a[1], b[0], b[1])
        .stroke({ color: '#000', width: 13, opacity: 0 })
        .attr({ 'pointer-events': 'stroke' });
      inter(hit, 'edge {' + e[0] + ',' + e[1] + '} — click to see its 2 list records and 2 matrix cells');
      hit.on('click', function () { selectEdge(e[0], e[1], true); });
    });
    for (var n = 1; n <= 5; n++) {
      (function (i) {
        var p = P[i], fill = GRAY, stk = BLACK, sw = 1.5;
        if (focus !== 'none' && +focus === i) { fill = FOC_BG; stk = FOC; sw = 3; }
        else if (sel && (sel[0] === i || sel[1] === i)) { fill = ACC_BG; stk = ACC; sw = 3; }
        else if (focus !== 'none' && adj[+focus].indexOf(i) >= 0) { fill = '#eaf3fc'; stk = FOC; sw = 2; }
        var c = draw.circle(R * 2).center(p[0], p[1]).fill(fill).stroke({ color: stk, width: sw });
        if (pend && (i === eu || i === ev)) {
          draw.circle(R * 2 + 9).center(p[0], p[1]).fill('none')
            .stroke({ color: '#8a8a8a', width: 1.1, dasharray: '3,4' });
        }
        inter(c, 'vertex ' + i + ' — degree ' + deg(i) + ' (chain length = row sum)');
        c.on('click', function () { selectVertex(i); });
        txt(i, p[0], p[1], 18).attr('pointer-events', 'none');
      })(n);
    }
    txt('(a)', 144, LABY, 20);

    /* ---------- panel (b) : adjacency lists ---------- */
    /* one contiguous 5-cell head column with a shared border */
    draw.rect(HEADW, ROWH * 5).move(HEADX, TOPY).fill(GRAY).stroke({ color: BLACK, width: 1.5 });
    for (var d = 1; d < 5; d++) {
      draw.line(HEADX, TOPY + d * ROWH, HEADX + HEADW, TOPY + d * ROWH).stroke({ color: BLACK, width: 1.2 });
    }
    for (var r = 1; r <= 5; r++) {
      (function (row, idx) {
        var cy = TOPY + idx * ROWH + ROWH / 2;
        if (focus !== 'none' && +focus === row) {
          draw.rect(HEADW, ROWH).move(HEADX, TOPY + idx * ROWH).fill(FOC_BG)
            .stroke({ color: FOC, width: 2.4 });
        }
        txt(row, HEADX - 12, cy, 18, '#000', 'end');

        var items = rowItems(row);
        if (items.length) arrow(HEADX + 9, cy, recX(0) - 2, cy, BLACK, 1.5);
        else draw.line(HEADX + 6, TOPY + idx * ROWH + ROWH - 6, HEADX + HEADW - 6, TOPY + idx * ROWH + 6)
          .stroke({ color: BLACK, width: 1.5 });

        items.forEach(function (it, k) {
          var x = recX(k), y = cy - RECH / 2;
          var f = GRAY, s = BLACK, w = 1.5, tcol = '#000', acol = BLACK;
          if (it.st === 'ghost') { f = GHO_BG; s = GHO; w = 1.3; tcol = GHO; acol = GHO; }
          else if (it.st === 'added') { f = ADD_BG; s = ADD; w = 2.4; acol = ADD; }
          if (it.st !== 'ghost' && isSel(row, it.val)) { f = ACC_BG; s = ACC; w = 2.8; acol = ACC; }
          else if (it.st === 'normal' && focus !== 'none' && +focus === row) { f = FOC_BG; s = FOC; w = 2.2; acol = FOC; }

          var rect = draw.rect(RECW, RECH).move(x, y).fill(f)
            .stroke({ color: s, width: w, dasharray: it.st === 'ghost' ? '4,3' : null });
          draw.line(x + FLDW, y, x + FLDW, y + RECH).stroke({ color: s, width: it.st === 'ghost' ? 1 : 1.2 });
          txt(it.val, x + FLDW / 2, cy, 17, tcol);

          if (k < items.length - 1) arrow(x + RECW - 13, cy, recX(k + 1) - 2, cy, acol, 1.5);
          else draw.line(x + FLDW + 4, cy + 9.5, x + RECW - 4, cy - 9.5).stroke({ color: s, width: 1.4 });

          if (it.st === 'ghost') {
            draw.line(x + 2, cy, x + RECW - 2, cy).stroke({ color: GHO, width: 1.8 });
            inter(rect, 'unlinked record: ' + it.val + ' was removed from list[' + row + ']');
          } else {
            inter(rect, 'list[' + row + '] holds ' + it.val + ' — the copy of edge {' + row + ',' + it.val + '} stored at vertex ' + row);
            rect.on('click', function () { selectEdge(row, it.val, true); });
          }
        });
      })(r, r - 1);
    }
    txt('(b)', 478, LABY, 20);

    /* ---------- panel (c) : adjacency matrix ---------- */
    for (var j = 1; j <= 5; j++) txt(j, MX + (j - 0.5) * CS, MY - 17, 18);
    for (var i2 = 1; i2 <= 5; i2++) txt(i2, MX - 18, MY + (i2 - 0.5) * CS, 18);
    for (var a1 = 1; a1 <= 5; a1++) {
      for (var b1 = 1; b1 <= 5; b1++) {
        (function (i, j) {
          var val = has(i, j) ? 1 : 0;
          var cx = MX + (j - 0.5) * CS, cy = MY + (i - 0.5) * CS;
          var bg = null, tcol = '#000', ring = null;
          if (op && op.type === 'removed' && ((op.u === i && op.v === j) || (op.v === i && op.u === j))) { bg = GHO_BG; tcol = GHO; ring = GHO; }
          else if (op && op.type === 'added' && ((op.u === i && op.v === j) || (op.v === i && op.u === j))) { bg = ADD_BG; tcol = ADD; ring = ADD; }
          if (isSel(i, j)) { bg = ACC_BG; tcol = ACC; ring = ACC; }
          else if (!isSel(i, j) && focus !== 'none' && +focus === i && !ring) { bg = FOC_BG; }
          if (bg) draw.rect(CS, CS).move(MX + (j - 1) * CS, MY + (i - 1) * CS).fill(bg).stroke('none');
          if (ring) draw.rect(CS - 3, CS - 3).move(MX + (j - 1) * CS + 1.5, MY + (i - 1) * CS + 1.5)
            .fill('none').stroke({ color: ring, width: 2 });
          if (pendingActive && eu !== ev && ((eu === i && ev === j) || (ev === i && eu === j)) && !ring) {
            draw.rect(CS - 4, CS - 4).move(MX + (j - 1) * CS + 2, MY + (i - 1) * CS + 2)
              .fill('none').stroke({ color: '#8a8a8a', width: 1.1, dasharray: '3,4' });
          }
          txt(val, cx, cy, 18, tcol);
          var hit = draw.rect(CS, CS).move(MX + (j - 1) * CS, MY + (i - 1) * CS)
            .fill('#fff').opacity(0).attr('pointer-events', 'all');
          inter(hit, 'cell (' + i + ',' + j + ') = ' + val + (i === j ? ' — no self-loops' :
            (val ? ' — mirrored at (' + j + ',' + i + ')' : ' — no edge, but the cell still costs space')));
          if (val && i !== j) hit.css('cursor', 'pointer').on('click', function () { selectEdge(i, j, true); });
        })(a1, b1);
      }
    }
    draw.rect(CS * 5, CS * 5).move(MX, MY).fill('none').stroke({ color: BLACK, width: 1.7 });
    txt('(c)', MX + CS * 2.5, LABY, 20);

    /* ---------- status caption (only when something is highlighted) ---------- */
    var capText = caption();
    if (capText) {
      var col = sel ? ACC : (focus !== 'none' ? FOC : (op && op.type === 'added' ? ADD : GHO));
      var cap = txt(capText, W / 2, 318, 16, col);
      cap.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
    }

    var btn = document.getElementById('edgeEditInput');
    if (btn) btn.textContent = (eu === ev) ? 'pick u ≠ v' :
      (has(eu, ev) ? 'Remove edge {' + eu + ',' + ev + '}' : 'Add edge {' + eu + ',' + ev + '}');
  }

  /* ── control handlers ────────────────────────────────── */
  window.toggle_vertexFocus = function (v) { focus = v; if (v !== 'none') sel = null; render(); };
  window.update_endpointU = function (v) { eu = v; pendingActive = true; render(); };
  window.update_endpointV = function (v) { ev = v; pendingActive = true; render(); };
  window.trigger_edgeEdit = function () {
    if (eu === ev) return;
    var existed = has(eu, ev);
    if (existed) doRemove(eu, ev); else doAdd(eu, ev);
    sel = null; focus = 'none'; pendingActive = false;
    document.getElementById('vertexFocusInput').value = 'none';
    render();
    showPopup(existed ? 'Removed {' + eu + ',' + ev + '}' : 'Added {' + eu + ',' + ev + '}',
      existed
        ? 'Deletion touches BOTH representations twice: the lists require walking list[' + eu + '] and list[' + ev + '] to unlink one record each (O(degree)), while the matrix needs only two direct writes, (' + eu + ',' + ev + ') and (' + ev + ',' + eu + '), set to 0.'
        : 'One new edge becomes two new records — one spliced into list[' + eu + '], one into list[' + ev + '] — and two matrix cells, (' + eu + ',' + ev + ') and (' + ev + ',' + eu + '), flipped to 1. Updating only one side would corrupt the graph.');
  };
  window.resetGraphBtn = function () {
    adj = copyAdj(); ghosts = []; op = null; sel = null; focus = 'none'; pendingActive = false;
    document.getElementById('vertexFocusInput').value = 'none';
    render();
  };

  /* ── demo step player ────────────────────────────────── */
  var steps = [
    {
      title: 'One graph, three pictures',
      narration: 'The same five-vertex graph appears three ways: a drawing, five linked lists, and a 5×5 table of 0s and 1s. Nothing is highlighted yet — just notice that panel (b) holds 14 records while panel (c) spends 25 cells.',
      state: { vertexFocus: 'none', edgeEdit: 'idle', sel: null }
    },
    {
      title: 'Follow one edge',
      narration: 'Edge 2–5 is selected. The record “5” in list 2, the record “2” in list 5, and both cells (2,5) and (5,2) light up together: one edge, four stored copies of it in memory.',
      state: { vertexFocus: 'none', edgeEdit: 'idle', sel: [2, 5] }
    },
    {
      title: 'A vertex’s neighbours, three ways',
      narration: 'Focus vertex 2. Its four incident edges glow, its chain 1→5→3→4 lights up, and row 2 of the matrix shows four 1s. Degree, chain length and row sum are the same number.',
      state: { vertexFocus: '2', edgeEdit: 'idle', sel: null }
    },
    {
      title: 'A sparse vertex',
      narration: 'Switch focus to vertex 3. Only two edges, a two-record chain — but still a full five-cell matrix row. The matrix pays for absent edges; the lists do not.',
      state: { vertexFocus: '3', edgeEdit: 'idle', sel: null }
    },
    {
      title: 'Add the missing edge {1,3}',
      narration: 'u = 1, v = 3, added. A new line appears in the drawing, a record is spliced into list 1 AND into list 3, and cells (1,3) and (3,1) both flip from 0 to 1 — never just one of them.',
      state: { endpointU: 1, endpointV: 3, vertexFocus: 'none', edgeEdit: 'added', sel: null }
    },
    {
      title: 'Remove an existing edge {2,4}',
      narration: 'u = 2, v = 4, removed. Deleting from the lists means walking two chains to unlink two records (shown grayed out); in the matrix it is two direct cell writes. Same edit, very different work.',
      state: { endpointU: 2, endpointV: 4, vertexFocus: 'none', edgeEdit: 'removed', sel: null }
    }
  ];
  var cur = 0;

  function applyState(st) {
    adj = copyAdj(); ghosts = []; op = null; pendingActive = false;
    if (st.endpointU != null) {
      eu = st.endpointU;
      document.getElementById('endpointUInput').value = eu;
      document.getElementById('endpointUVal').value = eu;
    }
    if (st.endpointV != null) {
      ev = st.endpointV;
      document.getElementById('endpointVInput').value = ev;
      document.getElementById('endpointVVal').value = ev;
    }
    focus = st.vertexFocus || 'none';
    document.getElementById('vertexFocusInput').value = focus;
    if (st.edgeEdit === 'added') doAdd(eu, ev);
    else if (st.edgeEdit === 'removed') doRemove(eu, ev);
    sel = st.sel ? st.sel.slice() : null;
    render();
  }
  function setStep(i) {
    cur = (i + steps.length) % steps.length;
    var s = steps[cur];
    applyState(s.state);
    document.getElementById('demoNarration').innerHTML = '<b>' + s.title + '.</b> ' + s.narration;
    document.getElementById('stepLabel').textContent = (cur + 1) + ' / ' + steps.length;
  }
  window.nextStep = function () { setStep(cur + 1); };
  window.prevStep = function () { setStep(cur - 1); };

  setStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: One undirected graph can be stored either as adjacency lists or as an adjacency matrix, and in both representations every undirected edge {u,v} is recorded twice — once for u and once for v.
KEY INSIGHT (what students should walk away understanding): An undirected edge {u,v} is a single fact about the graph but is always stored twice — in list[u] and list[v], or in cells (u,v) and (v,u) — which is why |adjacency list records| = 2|E| and why the matrix is symmetric.
DEMO STEPS: 6 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "One undirected graph can be stored either as adjacency lists or as an adjacency matrix, and in both representations every undirected edge {u,v} is recorded twice — once for u and once for v.",
  "figureType": "diagram",
  "elements": [
    "Panel label (a) centered under the graph drawing",
    "Panel label (b) centered under the adjacency-list structure",
    "Panel label (c) centered under the adjacency matrix",
    "Graph (a): five gray filled circles with black outlines labeled 1 (upper left), 2 (upper right), 3 (far right), 4 (lower middle), 5 (lower left)",
    "Graph (a): seven straight black edges 1–2, 1–5, 2–5, 2–3, 2–4, 3–4, 4–5",
    "Adjacency list (b): vertical array of five gray head cells stacked in a single column, row-labeled 1..5 to their left",
    "Adjacency list (b): horizontal chain of two-field gray records to the right of each head cell; left field holds a vertex number, right field holds either a forward arrow or a diagonal slash (NIL)",
    "Adjacency list (b): arrows from each head cell into its first record and between consecutive records",
    "Adjacency list (b) contents: row 1 → 2, 5; row 2 → 1, 5, 3, 4; row 3 → 2, 4; row 4 → 2, 5, 3; row 5 → 4, 1, 2",
    "Adjacency matrix (c): bordered 5×5 grid of 0/1 entries",
    "Adjacency matrix (c): column headers 1..5 above the grid and row headers 1..5 to the left",
    "Adjacency matrix (c): zeros on the main diagonal, entries symmetric across the diagonal",
    "Highlight styling: selected edge drawn thick and colored, matching list records outlined, matching matrix cells shaded (same accent color)",
    "Caption/annotation area showing the currently selected edge or vertex, e.g. 'edge {2,5} stored in list[2] and list[5]; cells (2,5) and (5,2)'"
  ],
  "interactions": [
    {
      "id": "edgeLookup",
      "type": "click",
      "teaches": "That a single undirected edge has exactly three simultaneous encodings — one line in the drawing, two list records, and two symmetric matrix cells — so storage of an edge is duplicated."
    },
    {
      "id": "vertexFocus",
      "type": "toggle",
      "label": "Focus vertex",
      "options": [
        "none",
        "1",
        "2",
        "3",
        "4",
