        : 'One new edge becomes two new records — one spliced into list[' + eu + '], one into list[' + ev + '] — and two matrix cells, (' + eu + ',' + ev + ') and (' + ev + ',' + eu + '), flipped to 1. Updating only one side would corrupt the graph.');
  };
  window.resetGraphBtn = function () {
    adj = copyAdj(); ghosts = []; op = null; sel = null; focus = 'none'; pendingActive = false;
    document.getElementById('vertexFocusInput').value = 'none';
    render();
  };

  /* ── demo step player ────────────────────────────────── */
  var steps = [
    {
      title: 'One graph, three pictures',
      narration: 'The same five-vertex graph appears three ways: a drawing, five linked lists, and a 5×5 table of 0s and 1s. Nothing is highlighted yet — just notice that panel (b) holds 14 records while panel (c) spends 25 cells.',
      state: { vertexFocus: 'none', edgeEdit: 'idle', sel: null }
    },
    {
      title: 'Follow one edge',
      narration: 'Edge 2–5 is selected. The record “5” in list 2, the record “2” in list 5, and both cells (2,5) and (5,2) light up together: one edge, four stored copies of it in memory.',
      state: { vertexFocus: 'none', edgeEdit: 'idle', sel: [2, 5] }
    },
    {
      title: 'A vertex’s neighbours, three ways',
