      state: { endpointU: 2, endpointV: 4, vertexFocus: 'none', edgeEdit: 'removed', sel: null }
    }
  ];
  var cur = 0;

  function applyState(st) {
    adj = copyAdj(); ghosts = []; op = null; pendingActive = false;
